head.script:
scwin.onpageload = function () {
    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof generator1 !== 'undefined') {
        generator1.remove();
    }

    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // Generator 컴포넌트의 자식인 Group 생성
    let grp_comp = $c.gcm.getTestGroup();

    let strGenerator = '';
    let strNameSpace = $c.gcm.getNameSpace();

    strGenerator += '<w2:generator ' +strNameSpace+ ' id="generator1">';
    strGenerator += '<w2:pageControl id="generator1_child" style="width:150px; height:30px;" ev:onclick="scwin.generator1_child_onclick"></w2:pageControl>';
    strGenerator += '</w2:generator>';

    scwin.generator1 = await $p.dynamicCreate(
        "generator1",
        "generator",
        strGenerator,
        grp_comp
    );

    // pageControl 자식은 비동기 초기화되며, 동적 생성된 자식 템플릿의 clone 소스는 현재 렌더 사이클(onpageload)이
    //  끝난 뒤에야 준비된다. comp_init 을 await/for 로 블로킹하면 렌더가 진행되지 못해 계속 _cloneRecursive 로 실패하므로,
    //  setTimeout 으로 렌더 사이클 이후로 지연시켜 성공할 때까지 재시도한다(비블로킹).
    scwin.wf_insertGenChild = function (tryCount) {
        scwin.generator1.insertChildAsync().catch(function () {
            if (tryCount > 0) {
                setTimeout(function () { scwin.wf_insertGenChild(tryCount - 1); }, 100);
            }
        });
    };
    setTimeout(function () { scwin.wf_insertGenChild(20); }, 100);

    // Generator 컴포넌트의 자식이 아닌 standalone pageControl(target1) 생성
    $c.gcm.createBasicPageControl('', 'ev:onclick="scwin.target1_onclick"');
}
